-- 4) Дозаполнение ClassifierId у потомков, если в Excel пусто у листа, но есть у родителя
WHILE 1 = 1
BEGIN
    UPDATE pv SET [ClassifierId] = p.[ClassifierId], [ModifiedAt] = SYSUTCDATETIME()
    FROM [PhysicalVolumesKfo] pv
    INNER JOIN [PhysicalVolumesKfo] p ON p.[Id] = pv.[ParentId]
    WHERE pv.[ClassifierId] IS NULL AND p.[ClassifierId] IS NOT NULL;
    IF @@ROWCOUNT = 0 BREAK;
END;

WHILE 1 = 1
BEGIN
    UPDATE pv SET [ClassifierId] = p.[ClassifierId], [ModifiedAt] = SYSUTCDATETIME()
    FROM [PhysicalVolumesBer] pv
    INNER JOIN [PhysicalVolumesBer] p ON p.[Id] = pv.[ParentId]
    WHERE pv.[ClassifierId] IS NULL AND p.[ClassifierId] IS NOT NULL;
    IF @@ROWCOUNT = 0 BREAK;
END;

-- BER: ClassifierId из связанного КФО, если у БЕР всё ещё пусто
UPDATE ber SET [ClassifierId] = kfo.[ClassifierId], [ModifiedAt] = SYSUTCDATETIME()
FROM [PhysicalVolumesBer] ber
INNER JOIN [PhysicalVolumesKfo] kfo ON kfo.[Id] = ber.[PhysicalVolumeKfoId]
WHERE ber.[ClassifierId] IS NULL AND kfo.[ClassifierId] IS NOT NULL;

